CREATE TABLE schema_version_v3(version INTEGER PRIMARY KEY CHECK(version IN(1,2,3)),backend TEXT NOT NULL CHECK(backend='sqlite'),checksum TEXT NOT NULL) STRICT;
INSERT INTO schema_version_v3 SELECT * FROM schema_version;
DROP TABLE schema_version;
ALTER TABLE schema_version_v3 RENAME TO schema_version;
CREATE TABLE audit_event_v3(id TEXT PRIMARY KEY,org_id TEXT REFERENCES organization(id),subject_id TEXT,employee_id TEXT,operation TEXT NOT NULL CHECK(operation IN('OP-ORG-05','OP-ORG-06','OP-ORG-08','OP-SEC-01','OP-SEC-02','OP-SEC-03','OP-SEC-06','AUTH-LOGIN','AUTH-STEP-UP','AUTH-LOGOUT','AUTH-BIND','AUTH-UNBIND')),purpose TEXT NOT NULL CHECK(purpose IN('organization_management','security_administration','')),request_id TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('allowed','denied')),recorded_at INTEGER NOT NULL,grant_id TEXT,FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,grant_id) REFERENCES access_grant(org_id,id),CHECK(subject_id IS NULL OR org_id IS NOT NULL),CHECK(employee_id IS NULL OR org_id IS NOT NULL),CHECK(grant_id IS NULL OR org_id IS NOT NULL),CHECK(outcome<>'denied' OR employee_id IS NULL),CHECK(outcome<>'denied' OR grant_id IS NULL)) STRICT;
INSERT INTO audit_event_v3 SELECT * FROM audit_event;
DROP TABLE audit_event;
ALTER TABLE audit_event_v3 RENAME TO audit_event;
CREATE INDEX audit_subject ON audit_event(org_id,subject_id);
CREATE INDEX audit_employee ON audit_event(org_id,employee_id);
CREATE INDEX audit_grant ON audit_event(org_id,grant_id);
CREATE TABLE subject_identity(digest BLOB PRIMARY KEY CHECK(length(digest)=32),key_id TEXT NOT NULL DEFAULT 'legacy-process-key',key_version INTEGER NOT NULL CHECK(key_version>0),org_id TEXT NOT NULL,subject_id TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN(0,1)),UNIQUE(digest,org_id,subject_id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id)) STRICT;
CREATE INDEX identity_subject ON subject_identity(org_id,subject_id);
CREATE UNIQUE INDEX session_identity_owner ON session(token_hash,org_id,subject_id);
CREATE TABLE session_auth(token_hash BLOB PRIMARY KEY,org_id TEXT NOT NULL,subject_id TEXT NOT NULL,identity_digest BLOB NOT NULL,identity_key_id TEXT NOT NULL DEFAULT 'legacy-process-key',key_version INTEGER NOT NULL CHECK(key_version>0),created_at INTEGER NOT NULL,auth_time INTEGER,acr TEXT NOT NULL CHECK(length(acr)<=256),amr_json TEXT NOT NULL CHECK(length(amr_json)<=1024),FOREIGN KEY(token_hash,org_id,subject_id) REFERENCES session(token_hash,org_id,subject_id),FOREIGN KEY(identity_digest,org_id,subject_id) REFERENCES subject_identity(digest,org_id,subject_id),CHECK(auth_time IS NULL OR auth_time<=created_at)) STRICT;
CREATE INDEX session_auth_identity ON session_auth(identity_digest);
CREATE TABLE oidc_transaction(state_hash BLOB PRIMARY KEY CHECK(length(state_hash)=32),binding_hash BLOB NOT NULL CHECK(length(binding_hash)=32),sealed_bytes BLOB NOT NULL CHECK(length(sealed_bytes)>=28),key_version INTEGER NOT NULL CHECK(key_version=1),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL CHECK(expires_at>created_at AND expires_at<=created_at+600000000),mode TEXT NOT NULL CHECK(mode IN('login','step_up')),action TEXT NOT NULL CHECK(action IN('','pii.write','access_grant.manage')),return_route TEXT NOT NULL CHECK(length(return_route)<=128),previous_hash BLOB,expected_org TEXT,expected_subject TEXT,expected_epoch INTEGER,expected_identity BLOB,consumed INTEGER NOT NULL DEFAULT 0 CHECK(consumed IN(0,1)),issued_hash BLOB REFERENCES session(token_hash),FOREIGN KEY(previous_hash,expected_org,expected_subject) REFERENCES session(token_hash,org_id,subject_id),FOREIGN KEY(expected_org,expected_subject) REFERENCES subject(org_id,id),FOREIGN KEY(expected_identity,expected_org,expected_subject) REFERENCES subject_identity(digest,org_id,subject_id),CHECK((previous_hash IS NULL AND expected_org IS NULL AND expected_subject IS NULL AND expected_epoch IS NULL) OR (previous_hash IS NOT NULL AND expected_org IS NOT NULL AND expected_subject IS NOT NULL AND expected_epoch IS NOT NULL AND expected_epoch>0)),CHECK((mode='login' AND action='' AND expected_identity IS NULL) OR (mode='step_up' AND action IN('pii.write','access_grant.manage') AND previous_hash IS NOT NULL AND expected_identity IS NOT NULL)),CHECK(consumed=1 OR issued_hash IS NULL)) STRICT;
CREATE INDEX oidc_transaction_expiry ON oidc_transaction(expires_at);
CREATE INDEX oidc_transaction_previous ON oidc_transaction(previous_hash);
